"""Regenerates everything that is generated: `models.py` (datamodel-code-generator) and `resources.py` (gen_facade).

Usage: uv run python scripts/generate.py   (or `make generate`)
"""

from __future__ import annotations

import json
import re
import subprocess
import sys
import tempfile
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import gen_facade  # noqa: E402

GEN_DIR = gen_facade.ROOT / "src" / "beinfi" / "_generated"
HEADER = (
    "# GENERATED by scripts/generate.py (datamodel-code-generator) from api/openapi.sdk.json.\n"
    "# DO NOT EDIT. To change something, change the contract (in the monorepo) and run `make sync-contract`.\n"
)


def main() -> int:
    try:
        doc = json.loads(gen_facade.CONTRACT.read_text(encoding="utf-8"))
        ops = gen_facade.collect_ops(doc)
        sigs, extra = gen_facade.plan_signatures(doc, ops)
        derived = gen_facade.models_input(doc, extra)
    except gen_facade.ContractError as e:
        print(f"generate: {e}", file=sys.stderr)
        return 1

    GEN_DIR.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory() as tmp:
        src = Path(tmp) / "models.json"
        out = Path(tmp) / "models.py"
        src.write_text(json.dumps(derived, indent=2, sort_keys=True), encoding="utf-8")
        cmd = [
            sys.executable, "-m", "datamodel_code_generator",
            "--input", str(src),
            "--input-file-type", "openapi",
            "--output", str(out),
            "--output-model-type", "pydantic_v2.BaseModel",
            "--target-python-version", "3.10",
            "--no-use-union-operator",  # `X | Y` does not run in pydantic on Python 3.9
            "--collapse-root-models",
            "--field-constraints",
            "--naming-strategy", "enclosing-model",  # contract schemas keep their name; inline ones take the name of the model that contains them
            "--output-datetime-class", "datetime",
            # Fidelity to the wire: no EmailStr (extra dependency), no AnyUrl (rewrites the URL),
            # uuid as str (ids travel in dicts and paths without conversion).
            "--type-mappings", "email=string", "uri=string", "uuid=string",
            "--snake-case-field",
            "--allow-population-by-field-name",
            "--enum-field-as-literal", "all",
            "--use-standard-collections",
            "--use-double-quotes",
            "--use-schema-description",
            "--disable-timestamp",
            "--formatters", "black",
        ]
        proc = subprocess.run(cmd, capture_output=True, text=True)
        if proc.returncode != 0:
            sys.stderr.write(proc.stdout + proc.stderr)
            return proc.returncode
        models = out.read_text(encoding="utf-8")
    resources = gen_facade.generate(ops, sigs)
    # Every `m.Name` that resources.py uses must exist in models.py.
    defined = set(re.findall(r"^class (\w+)\(", models, flags=re.M)) | set(re.findall(r"^(\w+) = ", models, flags=re.M))
    used = set(re.findall(r"\bm\.(\w+)", resources))
    missing = sorted(used - defined)
    # The variants `Name1`, `Name2` must be those of the RootModel `Name`, not a renamed namesake.
    for name in sorted(used):
        base = re.fullmatch(r"(\w+?)(\d+)", name)
        root = re.search(rf"^class {base.group(1)}\(RootModel\[Union\[([^\]]*)\]\]\)", models, flags=re.M) if base else None
        if root and name not in re.findall(r"\w+", root.group(1)):
            missing.append(name)
    if missing:
        print(f"generate: resources.py uses models the generator did not produce: {missing}", file=sys.stderr)
        return 1
    (GEN_DIR / "models.py").write_text(HEADER + models, encoding="utf-8")
    (GEN_DIR / "resources.py").write_text(resources, encoding="utf-8")
    (GEN_DIR / "__init__.py").write_text(HEADER.replace("scripts/generate.py (datamodel-code-generator)", "scripts/generate.py"), encoding="utf-8")
    print(f"models.py + resources.py: {len(ops)} operations, {len(extra)} synthesized models")
    return 0


if __name__ == "__main__":
    sys.exit(main())
